<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/schema_helpers.php';
if(session_status()===PHP_SESSION_NONE)session_start();
function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$formId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$formId){http_response_code(400);exit('Thiếu mã biểu mẫu.');}
$stmt=$pdo->prepare('SELECT f.*,v.id version_id FROM forms f LEFT JOIN form_versions v ON v.id=f.current_version_id WHERE f.id=?');$stmt->execute([$formId]);$form=$stmt->fetch();if(!$form){http_response_code(404);exit('Không tìm thấy biểu mẫu.');}$versionId=(int)$form['version_id']; requireFormManager($pdo,$formId); $vstatus='draft'; if($versionId){$vq=$pdo->prepare('SELECT status FROM form_versions WHERE id=?');$vq->execute([$versionId]);$vstatus=(string)$vq->fetchColumn();}
$fields=[];if($versionId){$q=$pdo->prepare('SELECT id,label,field_key,field_type FROM fields WHERE version_id=? ORDER BY sort_order,id');$q->execute([$versionId]);$fields=$q->fetchAll();}
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if($vstatus==='published'){http_response_code(409);exit('Phiên bản đã công bố không thể sửa điều kiện. Hãy tạo phiên bản mới trước. <a href="form_builder.php?id='.$formId.'">Quay lại</a>');}
 $action=$_POST['action']??'';
 try{
  if($action==='delete'){$id=(int)($_POST['condition_id']??0);$q=$pdo->prepare('DELETE FROM conditions WHERE id=? AND version_id=?');$q->execute([$id,$versionId]);$success='Đã xóa điều kiện.';}
  elseif($action==='add'){$target=(int)($_POST['target_field_id']??0);$source=(int)($_POST['source_field_id']??0);$operator=$_POST['operator']??'equals';$compare=trim($_POST['comparison_value']??'');$act=$_POST['condition_action']??'show';$allowedOps=['equals','not_equals','greater_than','less_than','contains','is_empty','is_not_empty'];$allowedActions=['show','hide','require'];$ids=array_map('intval',array_column($fields,'id'));if(!$target||!$source||$target===$source||!in_array($target,$ids,true)||!in_array($source,$ids,true))throw new RuntimeException('Hãy chọn hai câu hỏi khác nhau trong cùng phiên bản.');if(!in_array($operator,$allowedOps,true)||!in_array($act,$allowedActions,true))throw new RuntimeException('Toán tử hoặc hành động không hợp lệ.');if(!in_array($operator,['is_empty','is_not_empty'],true)&&$compare==='')throw new RuntimeException('Nhập giá trị so sánh cho điều kiện này.');$q=$pdo->prepare('INSERT INTO conditions(version_id,target_field_id,source_field_id,operator,comparison_value,action) VALUES(?,?,?,?,?,?)');$q->execute([$versionId,$target,$source,$operator,json_encode($compare,JSON_UNESCAPED_UNICODE),$act]);$success='Đã thêm điều kiện.';}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Không lưu được điều kiện. Hãy kiểm tra bảng conditions.';}
}
$q=$pdo->prepare('SELECT c.*,t.label target_label,s.label source_label FROM conditions c JOIN fields t ON t.id=c.target_field_id JOIN fields s ON s.id=c.source_field_id WHERE c.version_id=? ORDER BY c.id DESC');$q->execute([$versionId]);$conditions=$q->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Điều kiện biểu mẫu</title><link rel="stylesheet" href="assets/form_builder.css"><style>body{background:#f6f5fb;color:#24213a;font-family:Arial,sans-serif}.wrap{max-width:1000px;margin:35px auto;padding:20px}.panel{background:#fff;padding:24px;border-radius:16px;margin:18px 0;box-shadow:0 6px 24px #26204a0c}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.grid label{display:block;font-weight:600;margin-bottom:6px}.grid select,.grid input{width:100%;padding:11px;border:1px solid #ddd8ec;border-radius:9px}.btn{padding:11px 16px;border:0;border-radius:9px;cursor:pointer}.btn-primary{background:#6d4aff;color:#fff}.notice{padding:12px;border-radius:9px;margin:12px 0}.err{background:#fff0f0;color:#9b1c1c}.ok{background:#eaf9ef;color:#176b37}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #eee} @media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a href="form_builder.php?id=<?=$formId?>">← Quay lại thiết kế</a><h1>Điều kiện hiển thị</h1><p>Trạng thái phiên bản: <b><?=esc($vstatus)?></b></p><p><b><?=esc($form['title'])?></b> · Cấu hình câu hỏi hiện/ẩn hoặc bắt buộc theo câu trả lời khác.</p><?php if($error):?><div class="notice err"><?=esc($error)?></div><?php endif;?><?php if($success):?><div class="notice ok"><?=esc($success)?></div><?php endif;?>
<section class="panel"><h2>Thêm điều kiện</h2><?php if(count($fields)<2):?><p>Cần ít nhất hai câu hỏi trong biểu mẫu trước khi tạo điều kiện.</p><?php else:?><form method="post"><input type="hidden" name="action" value="add"><div class="grid"><div><label>Câu hỏi bị tác động</label><select name="target_field_id" required><?php foreach($fields as $f):?><option value="<?=$f['id']?>"><?=esc($f['label'])?></option><?php endforeach;?></select></div><div><label>Dựa vào câu trả lời của</label><select name="source_field_id" required><?php foreach($fields as $f):?><option value="<?=$f['id']?>"><?=esc($f['label'])?></option><?php endforeach;?></select></div><div><label>Toán tử</label><select name="operator"><option value="equals">Bằng</option><option value="not_equals">Không bằng</option><option value="contains">Có chứa</option><option value="greater_than">Lớn hơn</option><option value="less_than">Nhỏ hơn</option><option value="is_empty">Để trống</option><option value="is_not_empty">Không để trống</option></select></div><div><label>Giá trị so sánh</label><input name="comparison_value" placeholder="Ví dụ: Có"></div><div><label>Hành động</label><select name="condition_action"><option value="show">Hiện câu hỏi</option><option value="hide">Ẩn câu hỏi</option><option value="require">Bắt buộc trả lời</option></select></div></div><p><button class="btn btn-primary">＋ Lưu điều kiện</button></p></form><?php endif;?></section>
<section class="panel"><h2>Điều kiện hiện có</h2><?php if(!$conditions):?><p>Chưa có điều kiện nào.</p><?php else:?><table><thead><tr><th>Câu hỏi</th><th>Điều kiện</th><th>Hành động</th><th></th></tr></thead><tbody><?php foreach($conditions as $c):$cv=json_decode($c['comparison_value']??'null',true);if(is_array($cv))$cv=json_encode($cv,JSON_UNESCAPED_UNICODE);?><tr><td><?=esc($c['target_label'])?></td><td>Nếu “<?=esc($c['source_label'])?>” <?=esc($c['operator'])?> <?=esc($cv??'')?></td><td><?=['show'=>'Hiện','hide'=>'Ẩn','require'=>'Bắt buộc'][$c['action']]??esc($c['action'])?></td><td><form method="post" onsubmit="return confirm('Xóa điều kiện này?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="condition_id" value="<?=$c['id']?>"><button class="btn" type="submit">Xóa</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?></section></main></body></html>
